    "CARD_INVALID_JSON" -> "рігколіркартка JSON сіткаРежимнемаєефект，будь ласкаперевіритиперевіритимистецтваштуктакнемаєзакінченовсе。"
    "CARD_TOO_LARGE" -> "рігколіркарткаобганятипозавеликийМаленькийобмеженнясистема，будь ласкапростийзмінитиналаштуватиЗвичайноабовибративибратиНавітьМаленькийзмистецтваштук。"
    "CARD_INVALID_UTF8" -> "рігколіркарткамистецтвакнигакомпілюватикоднемаєефект，потребахочуть UTF-8 компілюватикодз JSON мистецтваштук。"
    "CARD_UNSUPPORTED_SPEC" -> "тимчасовонемаєвідділенняутримуватицечасткарігколіркарткаГолосяскравийзсіткаРежим，будь ласкакерівництвопозадля V2 або V3 рігколіркартканазадВажкаспробувати。"
    "CARD_INVALID_PNG" -> "PNG мистецтваштукпошкодженняпоганоабовузолструктуранемаєзакінченовсе，будь ласкаВажкановийвнизнавантаженняОригіналпочатокрігколіркартка。"
    "CARD_INVALID_DATA" -> "рігколіркарткахарактерчастинасіткаРежимнемаєефект，будь ласкаперевіритиперевіритиназвасказати、мистецтвакнига、ВІДЧИНЕНОполебілийіВсерединівбудованийсвітмежакниганомервідповідно до。"
    else -> null
}
